{"content":"pub fn match_pattern(pattern: &str, text: &str) -> bool {
    let p_chars: Vec<char> = pattern.chars().collect();
    let t_chars: Vec<char> = text.chars().collect();

    fn recursive(p: &[char], t: &[char]) -> bool {
        if p.is_empty() {
            return t.is_empty();
        }

        if p.len() >= 2 && p[1] == '*' {
            for i in 0..=t.len() {
                if recursive(&p[2..], &t[i..]) {
                    return true;
                }
            }
            false
        } else {
            if !t.is_empty() && (p[0] == '.' || p[0] == t[0]) {
                return recursive(&p[1..], &t[1..]);
            }
            false
        }
    }

    recursive(&p_chars, &t_chars)
}

